const base = $('Build Project Index').itemMatching(0).json;
const out = $json.output || $json;
const mentioned = Array.isArray(out.mentioned_projects) ? out.mentioned_projects : [];
if (!mentioned.length) {
  return [{ json: { ...base, hasMentions: false, noActions: true } }];
}
const allActions = [];
for (const m of mentioned) {
  const actions = Array.isArray(m.actions) ? m.actions : [];
  for (const a of actions) {
    allActions.push({
      json: {
        ...base,
        hasMentions: true,
        project_client: m.project_client,
        work_type: (() => { const pc = (m.project_client || 'Internal').trim(); const llmType = a.work_type || null; if (llmType === 'new_business') return 'new_business'; if (pc !== '' && pc !== 'Internal') return 'client_work'; return llmType || 'in_the_business'; })(),
        action: a.action || 'update',
        existing_task_id: a.existing_task_id || null,
        task: a.task || '',
        status: a.status || null,
        latest_note: a.latest_note || '',
        next_step: a.next_step || '',
        lead: a.lead || '',
        confidence_score: (typeof a.confidence_score === 'number') ? a.confidence_score : null,
        confidence_label: a.confidence_label || null,
        confidence_reason: a.confidence_reason || null,
        write_mode: a.write_mode || null,
        evidence_summary: a.evidence_summary || null,
        match_reason: a.match_reason || null,
        meeting_id: null,
        calendar_event_id: base.calendar_event_id,
        errors: []
      }
    });
  }
}
if (!allActions.length) {
  return [{ json: { ...base, hasMentions: true, noActions: true } }];
}
return allActions;

